import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';
import type { ServerMessage, ClientMessage, WebServerOptions } from './types.js';
import { RunRegistry } from './run-registry.js';
import { createStatusBridge } from './status-bridge.js';
import { loadWorkflow } from '../core/workflow-loader.js';
import { getDefaultWorkDir } from '../core/config.js';

export async function startWebServer(options: WebServerOptions): Promise<Bun.Server> {
  const registry = new RunRegistry();
  const clients = new Set<any>();
  const WEB_DIST_DIR = join(import.meta.dir, '..', '..', 'web', 'dist');

  const broadcast = (msg: ServerMessage) => {
    const d = JSON.stringify(msg);
    for (const ws of clients) {
      ws.send(d);
    }
  };

  const MIME_MAP: Record<string, string> = {
    '.html': 'text/html',
    '.js': 'application/javascript',
    '.css': 'text/css',
    '.json': 'application/json',
    '.png': 'image/png',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
    '.woff': 'font/woff',
    '.woff2': 'font/woff2',
  };

  async function startWorkflow(workflowName: string, taskPrompt: string, maxConcurrent?: number): Promise<string> {
    const runId = registry.createRun(workflowName);
    broadcast({ type: 'workflow_started', summary: registry.getSummary(runId) });

    let workflow;
    try {
      workflow = await loadWorkflow(workflowName, options.cwd);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      const summary = registry.failRun(runId, msg);
      broadcast({ type: 'workflow_failed', summary, error: msg, phase: registry.getRun(runId)?.currentPhase ?? 'unknown' });
      return runId;
    }

    const bridge = createStatusBridge(runId, registry, broadcast);
    const workDir = getDefaultWorkDir(options.cwd, workflowName);

    // Fire-and-forget the workflow run
    workflow
      .run(taskPrompt, {
        cwd: options.cwd,
        workDir,
        maxConcurrentTasks: maxConcurrent,
        onStatus: bridge,
        signal: registry.getAbortController(runId)!.signal,
      })
      .then(() => {
        const summary = registry.completeRun(runId);
        broadcast({ type: 'workflow_complete', summary });
      })
      .catch((err: unknown) => {
        const msg = err instanceof Error ? err.message : String(err);
        const summary = registry.failRun(runId, msg);
        broadcast({ type: 'workflow_failed', summary, error: msg, phase: registry.getRun(runId)?.currentPhase ?? 'unknown' });
      });

    return runId;
  }

  const server = Bun.serve({
    hostname: options.host,
    port: options.port,

    async fetch(req, server) {
      // ─── WebSocket upgrade ────────────────────────────────────────────
      if (new URL(req.url).pathname === '/ws') {
        const upgraded = server.upgrade(req);
        if (!upgraded) {
          return new Response('WebSocket upgrade failed', { status: 400 });
        }
        return undefined;
      }
      const url = new URL(req.url);

      // ─── API routes ────────────────────────────────────────────────────
      if (url.pathname.startsWith('/api/')) {
        if (req.method === 'POST' && url.pathname === '/api/runs') {
          return (async () => {
            try {
              const body = (await req.json()) as { workflowName?: string; taskPrompt?: string; maxConcurrent?: number };
              if (!body.workflowName || !body.taskPrompt) {
                return new Response(JSON.stringify({ error: 'workflowName and taskPrompt are required' }), {
                  status: 400,
                  headers: { 'Content-Type': 'application/json' },
                });
              }
              const runId = await startWorkflow(body.workflowName, body.taskPrompt, body.maxConcurrent);
              return Response.json({ runId });
            } catch {
              return new Response(JSON.stringify({ error: 'Invalid JSON body' }), {
                status: 400,
                headers: { 'Content-Type': 'application/json' },
              });
            }
          })();
        }

        if (req.method === 'GET' && url.pathname === '/api/runs') {
          return Response.json(registry.getAllSummaries());
        }

        return new Response('Not Found', { status: 404 });
      }

      // ─── Static file serving ───────────────────────────────────────────
      let filePath = url.pathname === '/' ? '/index.html' : url.pathname;

      // Try to serve the requested file
      const fullPath = join(WEB_DIST_DIR, filePath);
      const ext = extname(filePath);

      try {
        const content = await readFile(fullPath);
        const mimeType = MIME_MAP[ext] ?? 'application/octet-stream';

        // Special handling for index.html – replace WS endpoint
        if (filePath === '/index.html') {
          const text = content.toString('utf-8');
          const wsEndpoint = `ws://${url.host}/ws`;
          const modified = text.replace('{{WS_ENDPOINT}}', wsEndpoint);
          return new Response(modified, {
            headers: { 'Content-Type': 'text/html' },
          });
        }

        return new Response(content, {
          headers: { 'Content-Type': mimeType },
        });
      } catch {
        // File not found – try index.html (SPA fallback) or placeholder
        try {
          const indexPath = join(WEB_DIST_DIR, 'index.html');
          const indexContent = await readFile(indexPath);
          const text = indexContent.toString('utf-8');
          const wsEndpoint = `ws://${url.host}/ws`;
          const modified = text.replace('{{WS_ENDPOINT}}', wsEndpoint);
          return new Response(modified, {
            headers: { 'Content-Type': 'text/html' },
          });
        } catch {
          // No index.html at all – placeholder
          return new Response(
            `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>engin</title></head>
<body>
  <h1>engin</h1>
  <p>Frontend not built. Run <code>cd web && npm run build</code>.</p>
  <script>window.__WS_ENDPOINT__ = "ws://${url.host}/ws";</script>
</body>
</html>`,
            {
              status: 200,
              headers: { 'Content-Type': 'text/html' },
            },
          );
        }
      }
    },

    websocket: {
      open(ws) {
        clients.add(ws);
        ws.send(JSON.stringify({ type: 'init', workflows: registry.getAllSummaries() }));
      },
      message(ws, msg) {
        let parsed: ClientMessage;
        try {
          parsed = JSON.parse(typeof msg === 'string' ? msg : msg.toString()) as ClientMessage;
        } catch {
          return; // Ignore invalid messages
        }

        switch (parsed.type) {
          case 'start_workflow': {
            // Fire and forget – don't await
            startWorkflow(parsed.workflowName, parsed.taskPrompt, parsed.maxConcurrent).catch(() => {});
            break;
          }
          case 'cancel_workflow': {
            const ctrl = registry.getAbortController(parsed.workflowId);
            if (ctrl) {
              ctrl.abort();
            }
            break;
          }
          case 'select_workflow': {
            // Currently no server-side action needed for selection
            break;
          }
        }
      },
      close(ws) {
        clients.delete(ws);
      },
    },
  });

  console.log(`Web server listening on http://${options.host}:${options.port}`);
  return server;
}

import { describe, expect, it, mock, beforeAll, afterAll, beforeEach, afterEach } from 'bun:test';
import { startWebServer } from '../../src/web/server.ts';
import type { WebServerOptions } from '../../src/web/types.ts';
import { RunRegistry } from '../../src/web/run-registry.ts';

// ─── Mock workflow modules ──────────────────────────────────────────────────

/**
 * We mock the workflow-loader module so that loadWorkflow returns a
 * controllable workflow without hitting the filesystem.
 */
let mockWorkflowRun = mock<(taskPrompt: string, opts: Record<string, unknown>) => Promise<void>>().mockImplementation(async () => {});
let mockWorkflowShouldFail = false;
let mockWorkflowErrorMsg = '';

mock.module('../../src/core/workflow-loader.ts', () => ({
  loadWorkflow: mock<(name: string, cwd: string) => Promise<{ run: typeof mockWorkflowRun }>>()
    .mockImplementation(async (name: string) => {
      if (mockWorkflowShouldFail) {
        throw new Error(mockWorkflowErrorMsg || 'Workflow failed to load');
      }
      return { run: mockWorkflowRun };
    }),
}));

// ─── Mock config ────────────────────────────────────────────────────────────

mock.module('../../src/core/config.ts', () => ({
  getDefaultWorkDir: mock<(cwd: string, name: string) => string>()
    .mockImplementation((cwd: string) => `${cwd}/.engin/work/test-workflow`),
}));

// ─── Helpers ────────────────────────────────────────────────────────────────

const TEST_OPTIONS: WebServerOptions = {
  host: '127.0.0.1',
  port: 0, // Let the OS pick a free port
  cwd: '/tmp/test-cwd',
};

/** Wait for a promise to resolve (useful for fire-and-forget workflows). */
function tick(): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, 0));
}

// ─── Tests ──────────────────────────────────────────────────────────────────

describe('startWebServer', () => {
  let server: Bun.Server;
  let baseUrl: string;

  beforeAll(async () => {
    // Reset mocks before starting the server
    mockWorkflowRun = mock().mockImplementation(async () => {});
    mockWorkflowShouldFail = false;
    mockWorkflowErrorMsg = '';

    server = await startWebServer(TEST_OPTIONS);
    baseUrl = `http://${server.hostname}:${server.port}`;
  });

  afterAll(() => {
    server?.stop();
  });

  // ─── Static file serving ───────────────────────────────────────────────

  describe('static file serving', () => {
    it('returns 200 for index.html with WS endpoint replacement', async () => {
      const res = await fetch(`${baseUrl}/`);
      expect(res.status).toBe(200);
      const text = await res.text();
      expect(text).toContain('<!DOCTYPE html>');
      // Should have replaced {{WS_ENDPOINT}} with actual ws URL
      expect(text).not.toContain('{{WS_ENDPOINT}}');
      expect(text).toContain(`ws://${server.hostname}:${server.port}/ws`);
    });

    it('serves index.html with text/html content type', async () => {
      const res = await fetch(`${baseUrl}/index.html`);
      expect(res.status).toBe(200);
      expect(res.headers.get('Content-Type')).toBe('text/html');
    });

    it('serves unknown routes with index.html (SPA fallback) when index.html exists', async () => {
      // The web dist has index.html, so unknown route should serve it
      const res = await fetch(`${baseUrl}/some/unknown/path`);
      expect(res.status).toBe(200);
      const text = await res.text();
      expect(text).toContain('<!DOCTYPE html>');
    });

    it('serves index.html with correct MIME type', async () => {
      const res = await fetch(`${baseUrl}/index.html`);
      expect(res.headers.get('Content-Type')).toBe('text/html');
    });

    it('serves .js assets with application/javascript content type', async () => {
      // Fetch the JS asset file from web/dist/assets/
      const res = await fetch(`${baseUrl}/assets/index-DyyqoESW.js`);
      expect(res.status).toBe(200);
      expect(res.headers.get('Content-Type')).toBe('application/javascript');
      const text = await res.text();
      expect(text.length).toBeGreaterThan(0);
    });

    it('serves .js.map files with default application/octet-stream content type', async () => {
      const res = await fetch(`${baseUrl}/assets/index-DyyqoESW.js.map`);
      expect(res.status).toBe(200);
      expect(res.headers.get('Content-Type')).toBe('application/octet-stream');
    });

    it('serves non-existent static files with index.html fallback (SPA)', async () => {
      const res = await fetch(`${baseUrl}/some/unknown/path`);
      expect(res.status).toBe(200);
      const text = await res.text();
      expect(text).toContain('<!DOCTYPE html>');
    });
  });

  // ─── API routes ────────────────────────────────────────────────────────

  describe('API routes', () => {
    beforeEach(() => {
      // Reset workflow behaviour for each API test
      mockWorkflowShouldFail = false;
      mockWorkflowRun = mock().mockImplementation(async () => {});
    });

    it('POST /api/runs - returns 400 when workflowName is missing', async () => {
      const res = await fetch(`${baseUrl}/api/runs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ taskPrompt: 'Do something' }),
      });
      expect(res.status).toBe(400);
      const body = await res.json();
      expect(body.error).toContain('workflowName');
    });

    it('POST /api/runs - returns 400 when taskPrompt is missing', async () => {
      const res = await fetch(`${baseUrl}/api/runs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workflowName: 'test-workflow' }),
      });
      expect(res.status).toBe(400);
      const body = await res.json();
      expect(body.error).toContain('taskPrompt');
    });

    it('POST /api/runs - returns 400 for invalid JSON', async () => {
      const res = await fetch(`${baseUrl}/api/runs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: 'not-json',
      });
      expect(res.status).toBe(400);
      const body = await res.json();
      expect(body.error).toContain('JSON');
    });

    it('POST /api/runs - starts a workflow and returns runId', async () => {
      const res = await fetch(`${baseUrl}/api/runs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workflowName: 'test-workflow', taskPrompt: 'Build something', maxConcurrent: 3 }),
      });
      expect(res.status).toBe(200);
      const body = await res.json() as { runId: string };
      expect(body.runId).toBeDefined();
      expect(typeof body.runId).toBe('string');
      expect(body.runId.length).toBeGreaterThan(0);
    });

    it('POST /api/runs - returns 200 when workflow load fails (still returns runId)', async () => {
      mockWorkflowShouldFail = true;
      mockWorkflowErrorMsg = 'Workflow not found';

      const res = await fetch(`${baseUrl}/api/runs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workflowName: 'nonexistent', taskPrompt: 'Do it' }),
      });
      expect(res.status).toBe(200);
      const body = await res.json() as { runId: string };
      expect(body.runId).toBeDefined();
      // The run is created even if load fails
    });

    it('GET /api/runs - returns an array', async () => {
      const res = await fetch(`${baseUrl}/api/runs`);
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(Array.isArray(body)).toBe(true);
    });

    it('GET /api/runs - returns array of summaries after starting a workflow', async () => {
      // Start a workflow
      await fetch(`${baseUrl}/api/runs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workflowName: 'test-workflow', taskPrompt: 'Test' }),
      });

      const res = await fetch(`${baseUrl}/api/runs`);
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(Array.isArray(body)).toBe(true);
      if (body.length > 0) {
        expect(body[0]).toHaveProperty('id');
        expect(body[0]).toHaveProperty('workflowName');
        expect(body[0]).toHaveProperty('status');
      }
    });

    it('returns 404 for unknown API paths', async () => {
      const res = await fetch(`${baseUrl}/api/unknown`);
      expect(res.status).toBe(404);
    });
  });

  // ─── WebSocket ─────────────────────────────────────────────────────────

  describe('WebSocket', () => {
    let ws: WebSocket;
    const receivedMessages: any[] = [];

    beforeEach(() => {
      receivedMessages.length = 0;
      // Reset workflow behaviour
      mockWorkflowShouldFail = false;
      mockWorkflowRun = mock().mockImplementation(async () => {});
    });

    afterEach(() => {
      ws?.close();
    });

    it('sends init message upon connection with workflows list', async () => {
      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      const msg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('open', () => {
          // After open, we expect an init message
        });
        ws.addEventListener('message', (event) => {
          try {
            resolve(JSON.parse(event.data as string));
          } catch (e) {
            reject(e);
          }
        });
        ws.addEventListener('error', (event) => {
          reject(new Error('WebSocket error'));
        });
        // Timeout after 2 seconds
        setTimeout(() => reject(new Error('Timeout waiting for init message')), 2000);
      });

      expect(msg.type).toBe('init');
      expect(Array.isArray(msg.workflows)).toBe(true);
    });

    it('receives workflow_started after sending start_workflow message', async () => {
      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send start_workflow
      ws.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'test-workflow',
        taskPrompt: 'Build a feature',
        maxConcurrent: 2,
      }));

      // Wait for workflow_started
      const msg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          try {
            resolve(JSON.parse(event.data as string));
          } catch (e) {
            reject(e);
          }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_started')), 2000);
      });

      expect(msg.type).toBe('workflow_started');
      expect(msg.summary).toBeDefined();
      expect(msg.summary.workflowName).toBe('test-workflow');
      expect(msg.summary.status).toBe('running');
    });

    it('receives workflow_complete after workflow run succeeds', async () => {
      // Make the mock workflow resolve successfully
      mockWorkflowRun = mock().mockImplementation(async () => {});

      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send start_workflow
      ws.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'test-workflow',
        taskPrompt: 'Do work',
      }));

      // Wait for workflow_started
      await new Promise<void>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          const msg = JSON.parse(event.data as string);
          if (msg.type === 'workflow_started') resolve();
          else reject(new Error(`Unexpected message: ${msg.type}`));
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_started')), 2000);
      });

      // Wait for workflow_complete
      const completeMsg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          try {
            const msg = JSON.parse(event.data as string);
            if (msg.type === 'workflow_complete') resolve(msg);
            // Ignore intermediate messages (agent_log, workflow_phase, etc.)
          } catch (e) {
            reject(e);
          }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_complete')), 2000);
      });

      expect(completeMsg.type).toBe('workflow_complete');
      expect(completeMsg.summary.status).toBe('completed');
    });

    it('receives workflow_failed after workflow run throws', async () => {
      // Make the mock workflow reject
      mockWorkflowRun = mock().mockImplementation(async () => {
        throw new Error('Runtime error in workflow');
      });

      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send start_workflow
      ws.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'test-workflow',
        taskPrompt: 'Do work that fails',
      }));

      // Wait for workflow_started
      await new Promise<void>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          const msg = JSON.parse(event.data as string);
          if (msg.type === 'workflow_started') resolve();
          else reject(new Error(`Unexpected message: ${msg.type}`));
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_started')), 2000);
      });

      // Wait for workflow_failed
      const failMsg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          try {
            const msg = JSON.parse(event.data as string);
            if (msg.type === 'workflow_failed') resolve(msg);
          } catch (e) {
            reject(e);
          }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_failed')), 2000);
      });

      expect(failMsg.type).toBe('workflow_failed');
      expect(failMsg.summary.status).toBe('failed');
      expect(failMsg.error).toBe('Runtime error in workflow');
    });

    it('receives workflow_failed when workflow fails to load', async () => {
      mockWorkflowShouldFail = true;
      mockWorkflowErrorMsg = 'Workflow module not found';

      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send start_workflow
      ws.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'missing-workflow',
        taskPrompt: 'Do it',
      }));

      // Wait for workflow_started then workflow_failed (both sent)
      let started = false;
      const failMsg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          try {
            const msg = JSON.parse(event.data as string);
            if (msg.type === 'workflow_started') {
              started = true;
              return;
            }
            if (msg.type === 'workflow_failed') {
              resolve(msg);
            }
          } catch (e) {
            reject(e);
          }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_failed')), 2000);
      });

      expect(failMsg.type).toBe('workflow_failed');
      expect(failMsg.summary.status).toBe('failed');
      expect(failMsg.error).toBe('Workflow module not found');
    });

    it('cancel_workflow aborts the workflow', async () => {
      // Create a workflow that waits until aborted
      let abortSignal: AbortSignal | null = null;
      let abortPromiseResolve: (() => void) | null = null;
      mockWorkflowRun = mock().mockImplementation(async (_taskPrompt: string, opts: Record<string, unknown>) => {
        abortSignal = opts.signal as AbortSignal;
        // Wait until aborted, then throw to simulate cancellation
        await new Promise<void>((resolve) => {
          if (abortSignal?.aborted) {
            resolve();
            return;
          }
          abortSignal?.addEventListener('abort', () => resolve(), { once: true });
        });
        throw new Error('Workflow cancelled');
      });

      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send start_workflow
      ws.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'test-workflow',
        taskPrompt: 'Long running task',
      }));

      // Wait for workflow_started
      const startedMsg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          try {
            const msg = JSON.parse(event.data as string);
            if (msg.type === 'workflow_started') resolve(msg);
          } catch (e) {
            reject(e);
          }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_started')), 2000);
      });

      const runId = startedMsg.summary.id;

      // Send cancel_workflow
      ws.send(JSON.stringify({
        type: 'cancel_workflow',
        workflowId: runId,
      }));

      // The workflow should be aborted; wait for workflow_failed (since abort causes rejection)
      const failMsg = await new Promise<any>((resolve, reject) => {
        ws.addEventListener('message', (event) => {
          try {
            const msg = JSON.parse(event.data as string);
            if (msg.type === 'workflow_failed') resolve(msg);
          } catch (e) {
            reject(e);
          }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_failed after cancel')), 2000);
      });

      expect(failMsg.type).toBe('workflow_failed');
      // The abort signal should have been triggered
      expect(abortSignal?.aborted).toBe(true);
    });

    it('ignores invalid WebSocket messages without crashing', async () => {
      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send invalid JSON
      ws.send('not-json');
      // Send valid JSON but wrong shape (missing type)
      ws.send(JSON.stringify({ foo: 'bar' }));
      // Send unknown message type
      ws.send(JSON.stringify({ type: 'unknown_type' }));

      // The server should not crash; give it a tick
      await tick();
      expect(ws.readyState).toBe(WebSocket.OPEN);
    });

    it('handles select_workflow message without error', async () => {
      ws = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => {
        ws.addEventListener('message', () => resolve(), { once: true });
      });

      // Send select_workflow
      ws.send(JSON.stringify({ type: 'select_workflow', workflowId: 'some-id' }));

      // Should not crash; give it a tick
      await tick();
      expect(ws.readyState).toBe(WebSocket.OPEN);
    });

    it('can handle multiple concurrent WebSocket connections', async () => {
      const ws1 = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);
      const ws2 = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Both should receive init
      const msg1 = await new Promise<any>((resolve, reject) => {
        ws1.addEventListener('message', (event) => {
          try { resolve(JSON.parse(event.data as string)); } catch (e) { reject(e); }
        });
        setTimeout(() => reject(new Error('Timeout')), 2000);
      });

      const msg2 = await new Promise<any>((resolve, reject) => {
        ws2.addEventListener('message', (event) => {
          try { resolve(JSON.parse(event.data as string)); } catch (e) { reject(e); }
        });
        setTimeout(() => reject(new Error('Timeout')), 2000);
      });

      expect(msg1.type).toBe('init');
      expect(msg2.type).toBe('init');

      ws1.close();
      ws2.close();
    });

    it('broadcasts workflow_started to all connected clients', async () => {
      const ws1 = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);
      const ws2 = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for both to receive init
      await Promise.all([
        new Promise<void>((resolve) => ws1.addEventListener('message', () => resolve(), { once: true })),
        new Promise<void>((resolve) => ws2.addEventListener('message', () => resolve(), { once: true })),
      ]);

      // Start a workflow via WebSocket
      ws1.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'test-workflow',
        taskPrompt: 'Broadcast test',
      }));

      // Both clients should receive workflow_started
      const [msgFrom1, msgFrom2] = await Promise.all([
        new Promise<any>((resolve, reject) => {
          ws1.addEventListener('message', (event) => {
            try {
              const msg = JSON.parse(event.data as string);
              if (msg.type === 'workflow_started') resolve(msg);
            } catch (e) { reject(e); }
          });
          setTimeout(() => reject(new Error('Timeout ws1')), 2000);
        }),
        new Promise<any>((resolve, reject) => {
          ws2.addEventListener('message', (event) => {
            try {
              const msg = JSON.parse(event.data as string);
              if (msg.type === 'workflow_started') resolve(msg);
            } catch (e) { reject(e); }
          });
          setTimeout(() => reject(new Error('Timeout ws2')), 2000);
        }),
      ]);

      expect(msgFrom1.type).toBe('workflow_started');
      expect(msgFrom2.type).toBe('workflow_started');
      expect(msgFrom1.summary.id).toBe(msgFrom2.summary.id);
      expect(msgFrom1.summary.workflowName).toBe('test-workflow');

      ws1.close();
      ws2.close();
    });

    it('includes phase information in workflow_failed when workflow errors at runtime', async () => {
      // Simulate a workflow that first sets a phase then throws
      let capturedOnStatus: Record<string, unknown> | null = null;
      mockWorkflowRun = mock().mockImplementation(async (_taskPrompt: string, opts: Record<string, unknown>) => {
        capturedOnStatus = opts;
        // Simulate the workflow setting a phase before failing
        const onStatus = opts.onStatus as Record<string, Function>;
        if (onStatus?.onPhaseStart) {
          onStatus.onPhaseStart({ phase: 'execution' });
        }
        throw new Error('Execution error');
      });

      const testWs = new WebSocket(`ws://${server.hostname}:${server.port}/ws`);

      // Wait for init
      await new Promise<void>((resolve) => testWs.addEventListener('message', () => resolve(), { once: true }));

      // Send start_workflow
      testWs.send(JSON.stringify({
        type: 'start_workflow',
        workflowName: 'test-workflow',
        taskPrompt: 'Phase error test',
      }));

      // Wait for workflow_started
      await new Promise<void>((resolve, reject) => {
        testWs.addEventListener('message', (event) => {
          const msg = JSON.parse(event.data as string);
          if (msg.type === 'workflow_started') resolve();
          else reject(new Error(`Unexpected message: ${msg.type}`));
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_started')), 2000);
      });

      // Wait for workflow_failed
      const failMsg = await new Promise<any>((resolve, reject) => {
        testWs.addEventListener('message', (event) => {
          try {
            const msg = JSON.parse(event.data as string);
            if (msg.type === 'workflow_failed') resolve(msg);
          } catch (e) { reject(e); }
        });
        setTimeout(() => reject(new Error('Timeout waiting for workflow_failed')), 2000);
      });

      expect(failMsg.type).toBe('workflow_failed');
      expect(failMsg.phase).toBe('execution');
      expect(failMsg.error).toBe('Execution error');

      testWs.close();
    });
  });

  // ─── Server lifecycle ──────────────────────────────────────────────────

  describe('server lifecycle', () => {
    it('startWebServer returns a Bun.Server', async () => {
      const srv = await startWebServer({ host: '127.0.0.1', port: 0, cwd: '/tmp' });
      expect(srv).toBeDefined();
      expect(typeof srv.hostname).toBe('string');
      expect(typeof srv.port).toBe('number');
      expect(srv.port).toBeGreaterThan(0);
      srv.stop();
    });

    it('server stops without error', async () => {
      const srv = await startWebServer({ host: '127.0.0.1', port: 0, cwd: '/tmp' });
      expect(() => srv.stop()).not.toThrow();
    });

    it('can start multiple servers on different ports', async () => {
      const srv1 = await startWebServer({ host: '127.0.0.1', port: 0, cwd: '/tmp' });
      const srv2 = await startWebServer({ host: '127.0.0.1', port: 0, cwd: '/tmp' });
      expect(srv1.port).not.toBe(srv2.port);
      srv1.stop();
      srv2.stop();
    });

    it('logs the server URL to console after starting', async () => {
      const originalLog = console.log;
      const loggedMessages: string[] = [];
      console.log = (...args: string[]) => loggedMessages.push(args.join(' '));

      const srv = await startWebServer({ host: '127.0.0.1', port: 0, cwd: '/tmp' });

      console.log = originalLog;

      expect(loggedMessages.length).toBe(1);
      expect(loggedMessages[0]).toContain('Web server listening on');
      expect(loggedMessages[0]).toContain('http://127.0.0.1:');

      srv.stop();
    });
  });
});

/**
 * WebSocket protocol types for the engin web interface.
 *
 * These types define the message protocol between the server and connected
 * clients (e.g. the web UI). All messages are JSON-serialisable.
 *
 * Discriminated unions use the `type` field as the discriminant.
 */

// ─── Shared value types ─────────────────────────────────────────────────────

export interface PhaseDescriptor {
  id: string;
  label: string;
  icon: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type:
    | 'text'
    | 'thinking'
    | 'tool_call'
    | 'tool_call_start'
    | 'tool_call_end'
    | 'decision'
    | 'error';
  content: string;
  metadata?: Record<string, unknown>;
}

export interface AgentWindowState {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface SidebarInfo {
  title: string;
  indicator: string;
  phases?: PhaseDescriptor[];
}

export interface WorkflowSummary {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
}

// ─── Server → Client messages ───────────────────────────────────────────────

export type ServerMessage =
  | { type: 'init'; workflows: WorkflowSummary[] }
  | { type: 'workflow_started'; summary: WorkflowSummary }
  | { type: 'workflow_sidebar'; workflowId: string; sidebar: SidebarInfo }
  | { type: 'workflow_phase'; workflowId: string; phase: string; completed: string[] }
  | { type: 'workflow_complete'; summary: WorkflowSummary }
  | { type: 'workflow_failed'; summary: WorkflowSummary; error: string; phase: string }
  | { type: 'agent_spawned'; workflowId: string; agent: AgentWindowState }
  | { type: 'agent_log'; workflowId: string; agentId: string; entry: LogEntry }
  | { type: 'agent_complete'; workflowId: string; agentId: string };

// ─── Client → Server messages ───────────────────────────────────────────────

export type ClientMessage =
  | { type: 'start_workflow'; workflowName: string; taskPrompt: string; maxConcurrent?: number }
  | { type: 'select_workflow'; workflowId: string }
  | { type: 'cancel_workflow'; workflowId: string };

// ─── Server options ─────────────────────────────────────────────────────────

export interface WebServerOptions {
  host: string;
  port: number;
  cwd: string;
}

import type {
  AgentWindowState,
  LogEntry,
  PhaseDescriptor,
  SidebarInfo,
  WorkflowSummary,
} from './types.js';

// ─── Internal RunEntry ──────────────────────────────────────────────────────

interface RunEntry {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
  currentPhase: string;
  completedPhases: string[];
  agents: Map<string, AgentWindowState>;
  abortController: AbortController;
}

// ─── RunRegistry ────────────────────────────────────────────────────────────

/**
 * Tracks active and past workflow runs in memory.
 *
 * All run records are kept in insertion order so that clients can display a
 * stable, chronological list.  The registry exposes a high-level API that the
 * WebSocket server calls as workflow lifecycle events fire.
 */
export class RunRegistry {
  private runs: Map<string, RunEntry> = new Map();
  private order: string[] = [];

  // ─── Lifecycle ─────────────────────────────────────────────────────────

  /**
   * Create a new workflow run and return its unique ID.
   */
  createRun(workflowName: string): string {
    const id = crypto.randomUUID();
    const entry: RunEntry = {
      id,
      workflowName,
      status: 'running',
      sidebar: { title: workflowName, indicator: '...' },
      startedAt: new Date().toISOString(),
      currentPhase: '',
      completedPhases: [],
      agents: new Map(),
      abortController: new AbortController(),
    };
    this.runs.set(id, entry);
    this.order.push(id);
    return id;
  }

  /**
   * Mark a run as completed.  Returns the finished summary.
   * Throws if the run ID does not exist.
   */
  completeRun(runId: string): WorkflowSummary {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    entry.status = 'completed';
    entry.completedAt = new Date().toISOString();
    return this.toSummary(entry);
  }

  /**
   * Mark a run as failed.  Returns the finished summary.
   * Throws if the run ID does not exist.
   */
  failRun(runId: string, _errorMsg: string): WorkflowSummary {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    entry.status = 'failed';
    entry.completedAt = new Date().toISOString();
    return this.toSummary(entry);
  }

  // ─── Sidebar / Phase ───────────────────────────────────────────────────

  /**
   * Merge partial sidebar information into the run's sidebar.
   * Throws if the run ID does not exist.
   */
  updateSidebar(
    runId: string,
    info: { title?: string; indicator?: string; phases?: PhaseDescriptor[] },
  ): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    if (info.title !== undefined) {
      entry.sidebar.title = info.title;
    }
    if (info.indicator !== undefined) {
      entry.sidebar.indicator = info.indicator;
    }
    if (info.phases !== undefined) {
      entry.sidebar.phases = info.phases;
    }
  }

  /**
   * Advance the run to a new phase.  If a phase was already active it is
   * first pushed onto the completed list.
   * Throws if the run ID does not exist.
   */
  setPhase(runId: string, phase: string): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    if (entry.currentPhase) {
      entry.completedPhases.push(entry.currentPhase);
    }
    entry.currentPhase = phase;
  }

  // ─── Agents ────────────────────────────────────────────────────────────

  /**
   * Register (or replace) an agent window for the given run.
   * Throws if the run ID does not exist.
   */
  addAgent(runId: string, agent: AgentWindowState): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    entry.agents.set(agent.agentId, agent);
  }

  /**
   * Mark an agent as inactive (completed) within a run.
   * Throws if either the run ID or the agent ID does not exist.
   */
  completeAgent(runId: string, agentId: string): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    const agent = entry.agents.get(agentId);
    if (!agent) {
      throw new Error(`Agent ${agentId} not found in run ${runId}`);
    }
    agent.active = false;
  }

  /**
   * Append a log entry to an agent's log.  If the agent does not yet exist
   * it is auto-created with an empty profile and active=true.
   * Throws only if the run ID does not exist.
   */
  addAgentLogEntry(runId: string, agentId: string, logEntry: LogEntry): void {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    let agent = entry.agents.get(agentId);
    if (!agent) {
      agent = { agentId, profile: '', active: true, log: [logEntry] };
      entry.agents.set(agentId, agent);
    } else {
      agent.log.push(logEntry);
    }
  }

  // ─── Queries ───────────────────────────────────────────────────────────

  /**
   * Return a summary of a single run.
   * Throws if the run ID does not exist.
   */
  getSummary(runId: string): WorkflowSummary {
    const entry = this.runs.get(runId);
    if (!entry) {
      throw new Error(`Run ${runId} not found`);
    }
    return this.toSummary(entry);
  }

  /**
   * Return summaries of all runs in insertion order.
   */
  getAllSummaries(): WorkflowSummary[] {
    return this.order.map((id) => this.toSummary(this.runs.get(id)!));
  }

  /**
   * Return the raw entry (or undefined) for advanced internal use.
   */
  getRun(runId: string): RunEntry | undefined {
    return this.runs.get(runId);
  }

  /**
   * Return the AbortController for a run, or undefined if it doesn't exist.
   */
  getAbortController(runId: string): AbortController | undefined {
    return this.runs.get(runId)?.abortController;
  }

  // ─── Internal helpers ──────────────────────────────────────────────────

  private toSummary(entry: RunEntry): WorkflowSummary {
    return {
      id: entry.id,
      workflowName: entry.workflowName,
      status: entry.status,
      sidebar: entry.sidebar,
      startedAt: entry.startedAt,
      completedAt: entry.completedAt,
    };
  }
}

import type { StatusCallbacks, TurnContentBlock } from '../core/types.js';
import type { AgentWindowState, LogEntry, ServerMessage } from './types.js';
import { RunRegistry } from './run-registry.js';

/**
 * Create a `StatusCallbacks` object that forwards every lifecycle event to
 * the given `RunRegistry` (for state tracking) and broadcasts the
 * corresponding `ServerMessage` to connected WebSocket clients.
 */
export function createStatusBridge(
  runId: string,
  registry: RunRegistry,
  broadcast: (msg: ServerMessage) => void,
): StatusCallbacks {
  return {
    // ─── No-op callbacks ──────────────────────────────────────────────────

    onWorkflowStart() {},
    onWorkflowComplete() {},
    onWorkflowFailed() {},
    onTaskStart() {},
    onTaskComplete() {},
    onTaskRejected() {},
    onTurnStart() {},

    // ─── Phase ────────────────────────────────────────────────────────────

    onPhaseStart(info) {
      registry.setPhase(runId, info.phase);
      broadcast({
        type: 'workflow_phase',
        workflowId: runId,
        phase: info.phase,
        completed: [...registry.getRun(runId)!.completedPhases],
      });
    },

    onPhaseComplete(info) {
      broadcast({
        type: 'workflow_phase',
        workflowId: runId,
        phase: info.phase,
        completed: [...registry.getRun(runId)!.completedPhases],
      });
    },

    // ─── Agents ───────────────────────────────────────────────────────────

    onAgentSpawn(info) {
      const agent: AgentWindowState = {
        agentId: info.agentId,
        profile: info.profile,
        taskId: info.taskId,
        active: true,
        log: [],
      };
      registry.addAgent(runId, agent);
      broadcast({ type: 'agent_spawned', workflowId: runId, agent });
    },

    onAgentComplete(info) {
      registry.completeAgent(runId, info.agentId);
      broadcast({
        type: 'agent_complete',
        workflowId: runId,
        agentId: info.agentId,
      });
    },

    // ─── Turns ────────────────────────────────────────────────────────────

    onTurnEnd(info) {
      if (!info.contentBlocks || info.contentBlocks.length === 0) return;

      for (const block of info.contentBlocks) {
        const entry = contentBlockToLogEntry(block);
        registry.addAgentLogEntry(runId, info.agentId, entry);
        broadcast({
          type: 'agent_log',
          workflowId: runId,
          agentId: info.agentId,
          entry,
        });
      }
    },

    // ─── Tool calls ──────────────────────────────────────────────────────

    onToolCallStart(info) {
      const entry: LogEntry = {
        id: info.toolCallId,
        timestamp: new Date().toISOString(),
        type: 'tool_call_start',
        content: info.toolName,
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({
        type: 'agent_log',
        workflowId: runId,
        agentId: info.agentId,
        entry,
      });
    },

    onToolCallEnd(info) {
      const entry: LogEntry = {
        id: info.toolCallId + '-end',
        timestamp: new Date().toISOString(),
        type: 'tool_call_end',
        content: info.toolName,
        metadata: { isError: info.isError },
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({
        type: 'agent_log',
        workflowId: runId,
        agentId: info.agentId,
        entry,
      });
    },

    // ─── Errors ──────────────────────────────────────────────────────────

    onError(info) {
      const entry: LogEntry = {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        type: 'error',
        content: info.error,
        metadata: { phase: info.phase },
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({
        type: 'agent_log',
        workflowId: runId,
        agentId: info.agentId,
        entry,
      });
    },

    // ─── Decisions ───────────────────────────────────────────────────────

    onDecision(info) {
      const entry: LogEntry = {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        type: 'decision',
        content: info.decision,
        metadata: { reasoning: info.reasoning },
      };
      registry.addAgentLogEntry(runId, info.agentId, entry);
      broadcast({
        type: 'agent_log',
        workflowId: runId,
        agentId: info.agentId,
        entry,
      });
    },

    // ─── Sidebar ─────────────────────────────────────────────────────────

    onSidebarUpdate(info) {
      registry.updateSidebar(runId, info);
      broadcast({
        type: 'workflow_sidebar',
        workflowId: runId,
        sidebar: registry.getRun(runId)!.sidebar,
      });
    },
  };
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Map a `TurnContentBlock` to a `LogEntry`.
 */
function contentBlockToLogEntry(block: TurnContentBlock): LogEntry {
  switch (block.type) {
    case 'text':
      return {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        type: 'text',
        content: block.text,
      };
    case 'thinking':
      return {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        type: 'thinking',
        content: block.redacted ? '[redacted]' : block.thinking,
      };
    case 'toolCall':
      return {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        type: 'tool_call',
        content: block.name,
        metadata: { arguments: block.arguments },
      };
  }
}

import { describe, expect, it } from 'bun:test';
import { RunRegistry } from '../../src/web/run-registry.ts';
import type { WorkflowSummary } from '../../src/web/types.ts';

// ─── Helpers ────────────────────────────────────────────────────────────────

/** Return a fresh registry pre-populated with one run. */
function registryWithOneRun(): { registry: RunRegistry; runId: string } {
  const registry = new RunRegistry();
  const runId = registry.createRun('Test Workflow');
  return { registry, runId };
}

// ─── createRun ──────────────────────────────────────────────────────────────

describe('createRun', () => {
  it('returns a string ID', () => {
    const registry = new RunRegistry();
    const id = registry.createRun('My Workflow');
    expect(typeof id).toBe('string');
    expect(id.length).toBeGreaterThan(0);
  });

  it('returns a UUID-like string', () => {
    const registry = new RunRegistry();
    const id = registry.createRun('uuid-check');
    // UUID v4 pattern: xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx
    expect(id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
    );
  });

  it('stores the entry so getRun returns it', () => {
    const registry = new RunRegistry();
    const id = registry.createRun('Stored Run');
    const entry = registry.getRun(id);
    expect(entry).toBeDefined();
    expect(entry!.id).toBe(id);
    expect(entry!.workflowName).toBe('Stored Run');
    expect(entry!.status).toBe('running');
  });

  it('sets sidebar title to workflow name and indicator to "..."', () => {
    const registry = new RunRegistry();
    const id = registry.createRun('Sidebar Check');
    const entry = registry.getRun(id);
    expect(entry!.sidebar.title).toBe('Sidebar Check');
    expect(entry!.sidebar.indicator).toBe('...');
  });

  it('sets startedAt to an ISO string', () => {
    const registry = new RunRegistry();
    const before = Date.now();
    const id = registry.createRun('Time Check');
    const after = Date.now();
    const entry = registry.getRun(id);
    const started = new Date(entry!.startedAt).getTime();
    expect(started).toBeGreaterThanOrEqual(before);
    expect(started).toBeLessThanOrEqual(after);
  });

  it('initialises currentPhase to empty string', () => {
    const { registry, runId } = registryWithOneRun();
    const entry = registry.getRun(runId);
    expect(entry!.currentPhase).toBe('');
  });

  it('initialises completedPhases to empty array', () => {
    const { registry, runId } = registryWithOneRun();
    const entry = registry.getRun(runId);
    expect(entry!.completedPhases).toEqual([]);
  });

  it('initialises agents to empty Map', () => {
    const { registry, runId } = registryWithOneRun();
    const entry = registry.getRun(runId);
    expect(entry!.agents.size).toBe(0);
  });

  it('creates an AbortController', () => {
    const { registry, runId } = registryWithOneRun();
    const ctrl = registry.getAbortController(runId);
    expect(ctrl).toBeInstanceOf(AbortController);
    expect(ctrl!.signal.aborted).toBe(false);
  });

  it('generates unique IDs for successive runs', () => {
    const registry = new RunRegistry();
    const id1 = registry.createRun('Run 1');
    const id2 = registry.createRun('Run 2');
    expect(id1).not.toBe(id2);
  });
});

// ─── completeRun ────────────────────────────────────────────────────────────

describe('completeRun', () => {
  it('sets status to completed', () => {
    const { registry, runId } = registryWithOneRun();
    registry.completeRun(runId);
    const entry = registry.getRun(runId);
    expect(entry!.status).toBe('completed');
  });

  it('sets completedAt to an ISO timestamp', () => {
    const { registry, runId } = registryWithOneRun();
    const before = Date.now();
    registry.completeRun(runId);
    const after = Date.now();
    const entry = registry.getRun(runId);
    expect(entry!.completedAt).toBeDefined();
    const completed = new Date(entry!.completedAt!).getTime();
    expect(completed).toBeGreaterThanOrEqual(before);
    expect(completed).toBeLessThanOrEqual(after);
