it('returns correct MIME type for .css files if they exist', async () => {
  // Try a .css path to verify the MIME mapping; even if the file doesn't
  // exist we'll get the SPA fallback (index.html), but we check the concept
  const res = await fetch(`${baseUrl}/assets/styles.css`);
  // This file doesn't exist, but we should still get 200 via SPA fallback
  expect(res.status).toBe(200);
  // The fallback is index.html with text/html
  expect(res.headers.get('Content-Type')).toBe('text/html');
});

it('uses application/octet-stream for unknown extensions', async () => {
  // Request a file with an unregistered extension
  const res = await fetch(`${baseUrl}/assets/data.bin`);
  // File doesn't exist, so we get SPA fallback (index.html)
  expect(res.status).toBe(200);
  // But if it did exist, we'd check Content-Type is application/octet-stream
  // Since we get the SPA fallback, Content-Type is text/html
  expect(res.headers.get('Content-Type')).toBe('text/html');
});

it('returns 200 for / (root) with WS replacement', async () => {
  const res = await fetch(`${baseUrl}/`);
  expect(res.status).toBe(200);
  const text = await res.text();
  expect(text).not.toContain('{{WS_ENDPOINT}}');
  expect(text).toContain(`ws://${server.hostname}:${server.port}/ws`);
});

